const { readFileSync, existsSync } = await import('node:fs');
const path = globalThis.input.note_path;
if (!path || !existsSync(path)) {
  throw new Error('Input note_path is missing or file does not exist');
}
globalThis.noteBuffer = readFileSync(path);

const { SupernoteX, toPdf } = await import('supernote-typescript');
const note = new SupernoteX(globalThis.noteBuffer);
const pdfBytes = await toPdf(note);
globalThis.pdfBytes = pdfBytes;
